#!/bin/sh
# Generate the reports from the output of resolve.py, then upload them to S3 if S3_BUCKET is set
set -e
# the prefix is a directory, make sure it ends with a /
case "$S3_PREFIX" in ""|*/) ;; *) S3_PREFIX="$S3_PREFIX/" ;; esac
/rpmwatcher/rpmwatcher.py --output /out --input /work --index-root "/$S3_PREFIX" "$@"
if [ -n "$S3_BUCKET" ]; then
    AWS="aws ${S3_ENDPOINT_URL:+--endpoint-url $S3_ENDPOINT_URL}"
    $AWS s3 sync --no-progress /out "s3://$S3_BUCKET/$S3_PREFIX"
    # the list of versions also includes the ones not generated by this run (archives),
    # whose dates are kept from the previous list
    versions=$($AWS s3 ls "s3://$S3_BUCKET/$S3_PREFIX" | awk '$1 == "PRE" { print $2 }')
    $AWS s3 cp --quiet "s3://$S3_BUCKET/${S3_PREFIX}index.html" /tmp/previous.html || true
    updated=$(cd /out && for v in */; do printf ' --updated %s' "$v"; done)
    /rpmwatcher/autoindex.py --previous /tmp/previous.html $updated /tmp/index.html "/$S3_PREFIX" $versions
    $AWS s3 cp --no-progress /tmp/index.html "s3://$S3_BUCKET/${S3_PREFIX}index.html"
fi
